#nullable enable // autogenerated

using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using MVZ2.Metas;
using MVZ2.Modding;
using MVZ2Logic.Localization;
using PVZEngine;
using UnityEngine;
using UnityEngine.AddressableAssets;
using static TMPro.SpriteAssetUtilities.TexturePacker_JsonArray;

namespace MVZ2.Managers
{
    public partial class ResourceManager : MonoBehaviour
    {
        #region 元数据列表
        public MusicMetaList? GetMusicMetaList(string nsp)
        {
            var modResource = main.ResourceManager.GetModResource(nsp);
            if (modResource == null)
                return null;
            return modResource.MusicMetaList;
        }
        #endregion

        #region 元数据
        public MusicMeta? GetMusicMeta(NamespaceID music)
        {
            if (music == null)
                return null;
            var modResource = GetModResource(music.SpaceName);
            if (modResource?.MusicMetaList == null)
                return null;
            foreach (var m in modResource.MusicMetaList.metas)
            {
                if (m.ID == music.Path)
                    return m;
            }
            return null;
        }
        public NamespaceID[] GetAllMusicID()
        {
            List<NamespaceID> list = new List<NamespaceID>();
            foreach (var modResource in modResources)
            {
                if (modResource?.MusicMetaList == null)
                    continue;
                list.AddRange(modResource.MusicMetaList.metas.Select(m => new NamespaceID(modResource.Namespace, m.ID)));
            }
            return list.ToArray();
        }
        #endregion

        public string GetMusicName(NamespaceID? musicID)
        {
            if (NamespaceID.IsValid(musicID))
            {
                var meta = GetMusicMeta(musicID);
                if (meta != null)
                {
                    return main.LanguageManager._p(LogicStrings.CONTEXT_MUSIC_NAME, meta.Name);
                }
            }
            return main.LanguageManager._p(LogicStrings.CONTEXT_MUSIC_NAME, LogicStrings.MUSIC_NAME_NONE);
        }

        #region 私有方法
        private async Task LoadInitModMusicClips(string nsp)
        {
            var modResource = GetModResource(nsp);
            if (modResource == null)
                return;
            var resources = await LoadLabeledResources<AudioClip>(nsp, Addressables.MergeMode.Intersection, "Init", "Music");
            foreach (var (id, res) in resources)
            {
                RegisterAudioClip(id, res);
            }
        }
        private async Task LoadMainModMusicClips(string nsp, TaskProgress progress)
        {
            var modResource = GetModResource(nsp);
            if (modResource == null)
                return;
            var resources = await LoadLabeledResources<AudioClip>(nsp, Addressables.MergeMode.Intersection, progress, "Main", "Music");
            foreach (var (id, res) in resources)
            {
                RegisterAudioClip(id, res);
            }
        }
        private void LoadUnlocks_Music(ModResource resource)
        {
            if (resource.MusicMetaList == null)
                return;
            foreach (var meta in resource.MusicMetaList.metas)
            {
                AddConditionListUnlocks(meta.UnlockConditions);
            }
        }
        #endregion
    }
}
